UPDATE eval_case
SET rubric         = #{rubric},
    rubric_version = #{rubricVersion}
WHERE id = #{id}

UPDATE eval_case
SET status = #{status}
WHERE id = #{id}

mapper.select:
SELECT id, platform AS platform, bot_id AS botId, group_id AS groupId, case_type AS caseType, scenario, rubric, rubric_version AS rubricVersion, origin, trace_ref AS traceRef, input_digest AS inputDigest, output_digest AS outputDigest, status, created_at AS createdAt, updated_at AS updatedAt FROM eval_case
AND case_type = #{caseType}
AND status = #{status}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

SELECT id, platform AS platform, bot_id AS botId, group_id AS groupId, case_type AS caseType, scenario, rubric, rubric_version AS rubricVersion, origin, trace_ref AS traceRef, input_digest AS inputDigest, output_digest AS outputDigest, status, created_at AS createdAt, updated_at AS updatedAt FROM eval_case WHERE status = 'ready' AND case_type IN
#{item}
ORDER BY id LIMIT #{limit}
